-- mod-forever-racials 2.0: racials for utility, classes for power.
--
-- The racials that stay new spells, the class masteries and the class cooldowns. The client gets
-- the same spell rows from patch-P (tools/build_patch.py, which prints the spell_dbc rows below
-- with --sql).
--
--   90102 Escape Artist             the root and snare immunity Escape Artist casts, 3 sec.
--   90105 Shatter Curse             Orc active: curse immunity, -10% magic damage taken, 8 sec.
--   90106 Touch of the Grave        Undead passive; its script rolls the chance and casts 90107.
--   90107 Touch of the Grave        the heal (was a drain that also hurt the target).
--   90111 Rapid Regeneration        Troll active: 5% of max health every 2 sec for 20 sec.
--   90140-90146                     physical masteries: +2% crit and hit with the class's weapons
--                                   (warrior, paladin, hunter, rogue, death knight, shaman, wands).
--   90147 Spell Mastery             +4% spell hit, +2% spell crit.
--   90148 Feral Mastery             +2% crit and hit in Cat and Bear Form.
--   90150-90159                     class cooldowns, 2 min, 15 sec: Battle Fury, Crusader's Zeal,
--                                   Pack Fury, Cutthroat Rush, Inner Fervor, Grave Fury, Ancestral
--                                   Fury, Arcane Fervor, Fel Frenzy, Wild Instinct.
--   90160, 90161                    Pack Fury's and Fel Frenzy's half on the pet, cast by script
--                                   only when there's a pet.
--
-- Also removes the previous version's spells (Big Game Hunter, Elune's Light, Eureka!, Expansive
-- Mind's hidden half, Plainsrunning, Cultivation) and Cultivation's herbs; the characters update
-- takes them off characters. The spell ids must match src/ForeverRacials.cpp. Idempotent: safe to
-- run again.

-- The previous version's spells.
DELETE FROM `spell_dbc` WHERE `ID` IN (90100, 90101, 90103, 90104, 90108, 90109, 90110);
DELETE FROM `spell_proc` WHERE `SpellId` = 90103;
DELETE FROM `spell_script_names` WHERE `ScriptName` IN ('spell_forever_blood_fury', 'spell_forever_eureka',
    'spell_forever_plainsrunning', 'spell_forever_cultivation');
DELETE FROM `gameobject_template` WHERE `entry` BETWEEN 9500700 AND 9500739;

DELETE FROM `spell_dbc` WHERE `ID` IN (90102, 90105, 90106, 90107, 90111, 90140, 90141, 90142, 90143, 90144, 90145, 90146, 90147, 90148, 90150, 90151, 90152, 90160, 90153, 90154, 90155, 90156, 90157, 90158, 90161, 90159);
